class Solution:
    def findAnagrams(self, s: str, p: str) -&gt; List[int]:
        cnt = Counter(p)
        res = []
        l = 0
        for r_i, r_v in enumerate(s):
            cnt[r_v] -= 1
            while cnt[r_v] &lt; 0:  # 当前字符多了，窗口不合法，收缩左边
                cnt[s[l]] += 1
                l += 1
            if r_i - l + 1 == len(p):
                res.append(l)
        return res

