class Solution:
    def reverseBetween(self, head: Optional[ListNode], left: int, right: int) -&gt; Optional[ListNode]:
        p0 = dum = ListNode(0, head)

        for _ in range(left - 1):
            p0 = p0.next

        cur = p0.next
        pre = None
        for _ in range(right - left + 1):
            tmp = cur.next
            cur.next = pre
            pre = cur
            cur = tmp

        p0.next.next = cur  # 原 left 节点（现尾）接上 right 后面的节点
        p0.next = pre        # p0 指向反转段的新头
        return dum.next

