class Solution:
    def mergeKLists(self, lists: list[ListNode | None]) -&gt; ListNode | None:
        cur = dum = ListNode(0)
        h_list = [head for head in lists if head]
        heapify(h_list)
        while h_list:
            s_node = heappop(h_list)
            if s_node.next:
                heappush(h_list, s_node.next)
            cur.next = s_node
            cur = cur.next
        return dum.next

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -&gt; Optional[ListNode]:
        cur = dum = ListNode(0)
        h = [(head.val, i, head) for i, head in enumerate(lists) if head]
        heapify(h)
        while h:
            _, i, node = heappop(h)
            if node.next:
                heappush(h, (node.next.val, i, node.next))
            cur.next = node
            cur = cur.next
        return dum.next

